import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.Arrays;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;int t = Integer.parseInt(line.trim());while (t-- > 0) {String line1 = br.readLine();if (line1 == null) break;StringTokenizer st = new StringTokenizer(line1);int n = Integer.parseInt(st.nextToken());int k = Integer.parseInt(st.nextToken());long[] a = new long[n];st = new StringTokenizer(br.readLine());for (int i = 0; i < n; i++) {a[i] = Long.parseLong(st.nextToken());}Arrays.sort(a);long maxBeauty = 0;for (int i = 0; i < k; i++) {maxBeauty += (a[n - 1 - i] * 2);}System.out.println(maxBeauty);}}}